const input = $input.first().json;
const body = input.body || input;
const intent = String(body.intent || '');
const vacancyId = Number(body.vacancy_id);
const candidateId = Number(body.candidate_id);
const actionId = String(body.action_id || '');
const aiInput = String(body.ai_input || '');
let actionType = '';
let slotLabel = '';
let targetVacancyId = 0;
try {
  const parsed = typeof aiInput === 'string' && aiInput.trim() ? JSON.parse(aiInput) : (aiInput || {});
  actionType = String(parsed.action_type || '');
  slotLabel = String(parsed.slot || '');
  targetVacancyId = Number(parsed.target_vacancy_id || 0);
} catch (e) {
  const t = String(aiInput || '').toLowerCase();
  if (t.includes('слот') || t.includes('интервью')) { actionType = 'schedule_interview'; }
  else if (t.includes('соседн') || t.includes('перенос')) { actionType = 'transfer_to_neighbouring_vacancy'; }
  else if (t.includes('отказ') || t.includes('отклон')) { actionType = 'prepare_candidate_message'; }
  else if (t.includes('этап') || t.includes('стади') || t.includes('продвин') || t.includes('воронк')) { actionType = 'advance_candidate'; }
}
if (!intent) { throw new Error('Вход требует intent'); }
if (intent === 'confirm_action' || intent === 'execute_action') {
  if (!actionId) { throw new Error('Действие требует action_id'); }
}
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const readActionSql = actionId ? "SELECT action_id, action_type, status, potok_candidate_id, source_vacancy_id, target_vacancy_id, payload FROM recruiter_compass.action_proposals WHERE action_id = '" + esc(actionId) + "' LIMIT 1" : "SELECT 1 WHERE false";
return [{ json: { intent: intent, vacancy_id: vacancyId, candidate_id: candidateId, action_id: actionId, action_type: actionType, slot_label: slotLabel, target_vacancy_id: targetVacancyId, read_action_sql: readActionSql } }];

const i = $input.first().json;
const allowed = ['advance_candidate', 'transfer_to_neighbouring_vacancy', 'prepare_candidate_message', 'schedule_interview'];
if (allowed.indexOf(i.action_type) < 0) { throw new Error('Неподдерживаемый тип действия: ' + i.action_type); }
if (!i.candidate_id) { throw new Error('Нужен candidate_id'); }
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const payload = { slot: i.slot_label || null, target_vacancy_id: i.target_vacancy_id || null };
const sql = "INSERT INTO recruiter_compass.action_proposals (action_type, status, potok_candidate_id, source_vacancy_id, target_vacancy_id, payload, idempotency_key, expires_at) VALUES ('" + esc(i.action_type) + "', 'ready_for_recruiter_confirmation', " + Number(i.candidate_id) + ", " + Number(i.vacancy_id) + ", " + (i.target_vacancy_id || 'NULL') + ", '" + esc(JSON.stringify(payload)) + "'::jsonb, gen_random_uuid(), now() + interval '7 days') RETURNING action_id, action_type, status";
return [{ json: { sql: sql, action_type: i.action_type, candidate_id: i.candidate_id } }];

const row = $input.first().json;
const labels = { advance_candidate: 'перевод кандидата на следующую стадию воронки', schedule_interview: 'бронь слота интервью', prepare_candidate_message: 'отказ кандидату с сообщением', transfer_to_neighbouring_vacancy: 'перенос на соседнюю вакансию' };
return [{ json: { ok: true, action_id: row.action_id, action_type: row.action_type, label: labels[row.action_type] || row.action_type, message: 'Действие зафиксировано как предложение. Ожидает подтверждения рекрутера.' } }];

const i = $input.first().json;
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const sql = "UPDATE recruiter_compass.action_proposals SET status = 'confirmed', recruiter_confirmed_by = 'recruiter', recruiter_confirmed_at = now() WHERE action_id = '" + esc(i.action_id) + "' AND status IN ('proposed','consent_required','ready_for_recruiter_confirmation') RETURNING action_id, status";
return [{ json: { sql: sql, action_id: i.action_id } }];

const rows = $input.all();
const confirmed = rows.some(function(r) { return r.json.status === 'confirmed'; });
return [{ json: { ok: confirmed, action_id: $('Собрать подтверждение').first().json.action_id, message: confirmed ? 'Действие подтверждено рекрутером.' : 'Действие не найдено или уже не в статусе ожидания.' } }];

const rows = $input.all();
const a = rows[0] && rows[0].json;
if (!a) { throw new Error('Действие не найдено'); }
if (a.status !== 'confirmed') { throw new Error('Действие не подтверждено (status=' + a.status + ')'); }
const payload = (typeof a.payload === 'object' && a.payload) ? a.payload : {};
return [{ json: { action_id: a.action_id, action_type: a.action_type, candidate_id: Number(a.potok_candidate_id), source_vacancy_id: Number(a.source_vacancy_id), target_vacancy_id: Number(a.target_vacancy_id) || Number(payload.target_vacancy_id) || 0, slot: payload.slot || '' } }];

const act = $('Проверить статус').first().json;
const job = $('Вакансия (этапы)').first().json;
const joinsObj = $('Связи вакансии').first().json;
const joins = (joinsObj && joinsObj.objects) || [];
const stages = (job && job.stages) || [];
const my = joins.find(function(j) { return Number(j.applicant_id) === act.candidate_id; });
let method = '';
let url = '';
let body = null;
let note = '';
if (act.action_type === 'advance_candidate' || act.action_type === 'schedule_interview') {
  if (!my) { throw new Error('Связь кандидата с вакансией не найдена'); }
  let target = null;
  if (act.action_type === 'advance_candidate') {
    const cur = stages.find(function(s) { return s.id === my.stage.id; });
    const curSerial = cur ? Number(cur.serial) : -1;
    target = stages.filter(function(s) { return Number(s.serial) === curSerial + 1; })[0];
    if (!target) { throw new Error('Следующей стадии нет — кандидат уже на последней'); }
    note = 'стадия: ' + (cur ? cur.name : '?') + ' -> ' + target.name;
  } else {
    target = stages.find(function(s) { return s.stage_type === 'interview_hr'; }) || stages.find(function(s) { return s.stage_type && s.stage_type.indexOf('interview') === 0; });
    if (!target) { throw new Error('Стадия интервью не найдена'); }
    note = 'стадия: ' + target.name + (act.slot ? '; слот: ' + act.slot : '');
  }
  method = 'PATCH';
  url = 'https://demo.app.potok.io/api/v3/ajs_joins/' + my.id + '.json';
  body = { stage_id: target.id };
} else if (act.action_type === 'transfer_to_neighbouring_vacancy') {
  if (!act.target_vacancy_id) { throw new Error('Не указана целевая вакансия'); }
  method = 'POST';
  url = 'https://demo.app.potok.io/api/v3/ajs_joins.json';
  body = { job_id: act.target_vacancy_id, applicant_id: act.candidate_id, stage_type: 'sourced' };
  note = 'перенос кандидата на вакансию ' + act.target_vacancy_id;
} else if (act.action_type === 'prepare_candidate_message') {
  method = '';
  url = '';
  body = null;
  note = 'сообщение об отказе подготовлено; отклонение в Potok рекрутер выполняет вручную';
} else {
  throw new Error('Неподдерживаемый тип исполнения: ' + act.action_type);
}
return [{ json: { action_id: act.action_id, action_type: act.action_type, join_id: my ? my.id : null, candidate_id: act.candidate_id, source_vacancy_id: act.source_vacancy_id, target_vacancy_id: act.target_vacancy_id, method: method, url: url, body: body, note: note } }];

const d = $('Определить действие').first().json;
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const eventData = { note: d.note, join_id: d.join_id, target_vacancy_id: d.target_vacancy_id || null };
const sql = "UPDATE recruiter_compass.action_proposals SET status = 'executed', executed_at = now() WHERE action_id = '" + esc(String(d.action_id)) + "' AND status = 'confirmed'; INSERT INTO recruiter_compass.action_audit (action_id, event_type, actor_type, event_data) VALUES ('" + esc(String(d.action_id)) + "', 'execution_succeeded', 'agent', '" + esc(JSON.stringify(eventData)) + "'::jsonb)";
return [{ json: { sql: sql, action_id: d.action_id, note: d.note } }];

const d = $('Определить действие').first().json;
const esc = function(s) { return String(s).replace(/'/g, "''"); };
const eventData = { note: d.note, join_id: d.join_id, target_vacancy_id: d.target_vacancy_id || null };
const sql = "UPDATE recruiter_compass.action_proposals SET status = 'executed', executed_at = now() WHERE action_id = '" + esc(String(d.action_id)) + "' AND status = 'confirmed'; INSERT INTO recruiter_compass.action_audit (action_id, event_type, actor_type, event_data) VALUES ('" + esc(String(d.action_id)) + "', 'execution_succeeded', 'agent', '" + esc(JSON.stringify(eventData)) + "'::jsonb)";
return [{ json: { sql: sql, action_id: d.action_id, note: d.note } }];
